        self.value = value
        self.left = None
        self.right = None

def count_leaf_nodes(nodes):
    """
    Counts the number of leaf nodes in a BST.

    Args:
        nodes: A list of integers representing the nodes of the BST.

    Returns:
        The number of leaf nodes in the BST.
    """
    if not nodes:
        return 0

    root = Node(nodes[0])
    for i in range(1, len(nodes)):
        insert_node(root, nodes[i])

    return count_leaf_nodes_recursive(root)

def insert_node(root, value):
